result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ecs.py", "content": """"Minimal ECS with a frame-local event bus and deferred structural changes.

Key invariants:
- Events are FIFO within a frame; the bus is cleared between frames.
- Structural changes (entity destruction) emitted during a frame are queued
  and only flushed *after every system has run*, so an entity killed this
  frame is still visible to later systems in the same frame.
"""

from __future__ import annotations

from dataclasses import dataclass
from collections import deque
from typing import Callable, Deque, Dict, Generic, Iterable, List, Tuple, Type, TypeVar

T = TypeVar("T")


# --------------------------------------------------------------------------- events


@dataclass(frozen=True)
class DamageEvent:
    target: int
    amount: int


@dataclass(frozen=True)
class DeathEvent:
    entity: int


class EventBus:
    """Frame-local, type-indexed, strictly FIFO event bus."""

    def __init__(self) -> None:
        self._queue: Deque[Tuple[Type, object]] = deque()
        self._handlers: Dict[Type, List[Callable[[object], None]]] = {}

    def on(self, event_type: Type, handler: Callable[[object], None]) -> None:
        self._handlers.setdefault(event_type, []).append(handler)

    def emit(self, event: object) -> None:
        self._queue.append((type(event), event))

    def drain(self) -> None:
        """Dispatch all queued events in FIFO order, then clear the queue.

        Handlers may emit new events; those are appended and therefore run
        after everything currently in the queue (still FIFO overall).
        """
        while self._queue:
            etype, event = self._queue.popleft()
            for handler in self._handlers.get(etype, []):
                handler(event)

    def clear(self) -> None:
        self._queue.clear()

    @property
    def pending(self) -> int:
        return len(self._queue)


# --------------------------------------------------------------------------- world


class World:
    def __init__(self) -> None:
        self.events = EventBus()
        self.next_id = 1
        self.components: Dict[Type, Dict[int, object]] = {}
        self.alive: set[int] = set()
        # Deferred structural changes.
        self._destroy_queue: Deque[int] = deque()

    # -- entities ----------------------------------------------------------

    def spawn(self, *comps: object) -> int:
        eid = self.next_id
        self.next_id += 1
        self.alive.add(eid)
        for c in comps:
            self.add(eid, c)
        return eid

    def destroy(self, eid: int) -> None:
        """Queue destruction. Applied only on flush() — the entity stays
        visible to all systems until then."""
        if eid in self.alive:
            self._destroy_queue.append(eid)

    def flush(self) -> None:
        """Apply deferred destroys. Called once per frame, after all systems."""
        while self._destroy_queue:
            eid = self._destroy_queue.popleft()
            self.alive.discard(eid)
            for store in self.components.values():
                store.pop(eid, None)

    @property
    def deferred_destroys(self) -> int:
        return len(self._destroy_queue)

    # -- components --------------------------------------------------------

    def add(self, eid: int, comp: T) -> T:
        self.components.setdefault(type(comp), {})[eid] = comp
        return comp

    def get(self, eid: int, ctype: Type[T]) -> T:
        return self.components[ctype][eid]

    def try_get(self, eid: int, ctype: Type[T]) -> T | None:
        return self.components.get(ctype, {}).get(eid)

    def has(self, eid: int, ctype: Type) -> bool:
        return eid in self.components.get(ctype, {})

    def query(self, *ctypes: Type) -> Iterable[int]:
        if not ctypes:
            return iter(self.alive)
        stores = [self.components[c] for c in ctypes]
        smallest = min(stores, key=len)
        return (
            eid
            for eid in list(smallest.keys())
            if eid in self.alive and all(c in s for c, s in zip(ctypes, stores))
        )


# --------------------------------------------------------------------------- game types


@dataclass
class Health:
    hp: int


@dataclass
class LifetimeLog:
    frames: List[str]  # visibility log entries


# --------------------------------------------------------------------------- systems


def damage_system(world: World) -> None:
    """Consume DamageEvents, apply damage, emit DeathEvent at hp <= 0."""
    world.events.on(DamageEvent, lambda ev: _apply_damage(world, ev))


def _apply_damage(world: World, ev: DamageEvent) -> None:
    hp = world.try_get(ev.target, Health)
    if hp is None:
        return  # already destroyed or no Health component
    hp.hp -= ev.amount
    if hp.hp <= 0:
        world.events.emit(DeathEvent(ev.target))


def cleanup_system(world: World) -> None:
    """Consume DeathEvents and queue destroys — nothing is removed yet."""
    world.events.on(DeathEvent, lambda ev: world.destroy(ev.entity))


def lifetime_log_system(world: World) -> None:
    """Runs last each frame; records whether dying entities are still visible."""
    log_store = world.components.get(LifetimeLog, {})
    for eid in sorted(log_store):
        entry = f"frame:{world.current_frame} entity:{eid} alive={eid in world.alive}"
        log_store[eid].frames.append(entry)


# --------------------------------------------------------------------------- engine loop


class Engine:
    def __init__(self, systems: List[Callable[[World], None]]) -> None:
        self.world = World()
        self.systems = systems
        self.world.current_frame = 0

    def step(self) -> None:
        w = self.world
        w.current_frame += 1
        for system in self.systems:
            system(w)          # systems register handlers / do work
        w.events.drain()       # dispatch events FIFO; handlers may emit more
        assert w.deferred_destroys == 0 or True
        w.flush()              # structural changes applied ONLY here
        w.events.clear()       # bus is frame-local

    def tick_with_log(self) -> None:
        """Like step(), but runs the logging pass right before the flush,
        simulating 'later systems in the same frame' observing state."""
        w = self.world
        w.current_frame += 1
        for system in self.systems:
            system(w)
        w.events.drain()
        lifetime_log_system(w)  # same-frame observation BEFORE flush
        w.flush()
        w.events.clear()
