class LifetimeLogSystem:
    """A regular late-running system: observes entities BEFORE the flush,
    i.e. in the same frame they were killed."""

    def update(self, world: World) -> None:
        store = world.components.get(VisibilityLog, {})
        for eid in sorted(store):
            state = "alive" if eid in world.alive else "dead"
            store[eid].entries.append((world.frame, state))


