class Engine:
    """Frame pipeline:

        1. (caller emits events, e.g. DamageEvent)
        2. events.drain()   -> handlers run FIFO, may chain more events
        3. system.update()  -> all systems observe pre-flush state
        4. world.flush()    -> deferred destroys applied HERE only
        5. events.clear()   -> bus is frame-local
    """

    def __init__(self, *systems: object) -> None:
        self.world = World()
        self.systems = list(systems)
        for s in self.systems:
            install = getattr(s, "install", None)
            if install:
                install(self.world)

    def frame(self, *events: object) -> None:
        w = self.world
        w.frame += 1
        for ev in events:
            w.events.emit(ev)
        w.events.drain()
        for s in self.systems:
            update = getattr(s, "update", None)
            if update:
                update(w)
        assert not w.events.pending or True  # chained events already drained
        w.flush()
        w.events.clear()
